import React, { useState } from "react";
import axios from "axios";

export default function ImageProcessor({ colorblindType, mode }) {
  const [original, setOriginal] = useState(null);
  const [processed, setProcessed] = useState(null);
  const [loading, setLoading] = useState(false);

  const handleFile = async (e) => {
    const file = e.target.files[0];
    if (!file) return;

    const preview = URL.createObjectURL(file);
    setOriginal(preview);
    setProcessed(null);

    const formData = new FormData();
    formData.append("file", file);
    formData.append("type", colorblindType);
    formData.append("mode", mode);

    setLoading(true);
    const res = await axios.post(
      "http://localhost:5000/api/image",
      formData,
      { responseType: "blob" }
    );

    setProcessed(URL.createObjectURL(res.data));
    setLoading(false);
  };

  return (
    <div style={card}>
      <input type="file" accept="image/*" onChange={handleFile} />

      {(original || processed) && (
        <div style={row}>
          {original && (
            <div style={box}>
              <h3>Original</h3>
              <img src={original} style={img} />
            </div>
          )}

          {processed && (
            <div style={box}>
              <h3>Output</h3>
              <img src={processed} style={img} />
            </div>
          )}
        </div>
      )}

      {loading && <p>Processing...</p>}
    </div>
  );
}

const card = {
  background: "#fff",
  padding: "20px",
  borderRadius: "14px",
  width: "100%",
  maxWidth: "1200px",
  margin: "0 auto",
  boxSizing: "border-box",
};

const row = {
  display: "flex",
  gap: "20px",
  marginTop: "20px",
  width: "100%",
};

const box = {
  flex: "1",
  border: "1px solid #ddd",
  borderRadius: "10px",
  padding: "10px",
  textAlign: "center",
  overflow: "hidden",
};

const img = {
  width: "100%",
  height: "350px",
  objectFit: "contain",
  display: "block",
};
